<?php $currentRow=is_array($damodaramRow??null)?$damodaramRow:[]; $industry=(string)($damodaramIndustry??''); $year=(int)($damodaramYear??2024); $chartConfigs=['risk'=>['type'=>'bar','data'=>['labels'=>['Beta','Unlevered Beta','Debt/Equity','Cash/Firm Value','Tax Rate'],'datasets'=>[[ 'label'=>$industry,'data'=>[(float)($currentRow['beta']??0),(float)($currentRow['unlevered_beta']??0),(float)($currentRow['debt_to_equity']??0),(float)($currentRow['cash_firm_value']??0),(float)($currentRow['tax_rate']??0)] ]]],'options'=>['responsive'=>true,'maintainAspectRatio'=>false,'plugins'=>['legend'=>['display'=>false]]]],'beta'=>['type'=>'radar','data'=>['labels'=>['Avg Unlevered','Avg Levered','Total Unlevered','Total Levered','Market Corr'],'datasets'=>[[ 'label'=>$industry,'data'=>[(float)($currentRow['avg_unlevered_beta']??0),(float)($currentRow['avg_levered_beta']??0),(float)($currentRow['total_unlevered_beta']??0),(float)($currentRow['total_levered_beta']??0),(float)($currentRow['market_correlation']??0)] ]]],'options'=>['responsive'=>true,'maintainAspectRatio'=>false]]]; ?>
<article class="module-card dam-card"><h2 class="dam-title">Damodaran BI · Risk / Capital</h2><div class="dam-meta"><span class="dam-chip">Indústria: <?= h($industry) ?></span><span class="dam-chip">Ano: <?= h((string)$year) ?></span></div><div class="dam-chart-shell" data-dam-chart="risk" data-chart-configs='<?= h((string)json_encode($chartConfigs, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?>'><div class="dam-chart-top"><strong>Gráficos</strong><div class="dam-chart-buttons"><button type="button" class="dam-chart-btn" data-chart-key="risk">Risco</button><button type="button" class="dam-chart-btn" data-chart-key="beta">Betas</button></div></div><div class="dam-canvas-wrap"><canvas></canvas></div></div><div class="dam-table-wrap"><table class="dam-table"><?php if(!empty($currentRow)): ?><thead><tr><?php foreach(array_keys($currentRow) as $col): ?><th><?= h((string)$col) ?></th><?php endforeach; ?></tr></thead><tbody><tr><?php foreach($currentRow as $value): ?><td><?= h((string)$value) ?></td><?php endforeach; ?></tr></tbody><?php else: ?><tbody><tr><td>Sem dados.</td></tr></tbody><?php endif; ?></table></div></article><script>(function(){const root=document.querySelector('[data-dam-chart="risk"]');if(!root||!window.Chart)return;const canvas=root.querySelector('canvas');const buttons=[...root.querySelectorAll('[data-chart-key]')];const configs=JSON.parse(root.getAttribute('data-chart-configs')||'{}');let chart=null;function render(key){const cfg=configs[key];if(!cfg)return;buttons.forEach(b=>b.classList.toggle('is-active',b.getAttribute('data-chart-key')===key));if(chart)chart.destroy();chart=new Chart(canvas.getContext('2d'),cfg);}buttons.forEach(b=>b.addEventListener('click',()=>render(b.getAttribute('data-chart-key'))));if(buttons[0])render(buttons[0].getAttribute('data-chart-key'));})();</script>